117→func configureDroidRepoSettings(repoDir string) error {
118→	home, err := os.UserHomeDir()
119→	if err != nil {
120→		return fmt.Errorf("get home dir: %w", err)
121→	}
122→
123→	globalSettingsPath := filepath.Join(home, ".factory", "settings.json")
124→	repoSettingsPath := filepath.Join(repoDir, droidRepoSettingsPath)
125→
126→	if err := mergeDroidCustomModels(globalSettingsPath, repoSettingsPath); err != nil {
127→		return err
128→	}
129→	if err := ensureGitInfoExcludeContains(repoDir, droidRepoSettingsPath); err != nil {
130→		return fmt.Errorf("exclude droid settings from git: %w", err)
131→	}
132→	return nil
133→}
134→
135→func mergeDroidCustomModels(globalSettingsPath, repoSettingsPath string) error {
136→	globalSettings, err := loadJSONMap(globalSettingsPath, "global droid settings")
137→	if err != nil {
138→		return err
139→	}
140→
141→	customModels, ok := globalSettings["customModels"]
142→	if !ok {
143→		return fmt.Errorf(
144→			"global droid settings at %s missing customModels; repo-local %s shadows global settings",
145→			globalSettingsPath,
146→			repoSettingsPath,
147→		)
148→	}
149→
150→	var models []json.RawMessage
151→	if err := json.Unmarshal(customModels, &models); err != nil {
152→		return fmt.Errorf("parse customModels in %s: %w", globalSettingsPath, err)
153→	}
154→	if len(models) == 0 {
155→		return fmt.Errorf("global droid settings at %s has empty customModels", globalSettingsPath)
156→	}
157→
158→	repoSettings, err := loadJSONMap(repoSettingsPath, "repo-local droid settings")
159→	if err != nil {
160→		return err
161→	}
162→	repoSettings["customModels"] = customModels
163→
164→	out, err := json.MarshalIndent(repoSettings, "", "  ")
165→	if err != nil {
166→		return fmt.Errorf("marshal repo-local droid settings: %w", err)
167→	}
168→	out = append(out, '\n')
169→
170→	if err := os.WriteFile(repoSettingsPath, out, 0o600); err != nil {
171→		return fmt.Errorf("write repo-local droid settings %s: %w", repoSettingsPath, err)
172→	}
173→	return nil
174→}
175→
176→func loadJSONMap(path, description string) (map[string]json.RawMessage, error) {
177→	data, err := os.ReadFile(path)
178→	if err != nil {
179→		return nil, fmt.Errorf("read %s at %s: %w", description, path, err)
180→	}
181→
182→	var parsed map[string]json.RawMessage
183→	if err := json.Unmarshal(data, &parsed); err != nil {
184→		return nil, fmt.Errorf("parse %s at %s: %w", description, path, err)
185→	}
186→	if parsed == nil {
187→		parsed = make(map[string]json.RawMessage)
188→	}
189→	return parsed, nil
190→}
191→
192→func ensureGitInfoExcludeContains(repoDir, entry string) error {
193→	excludePath := filepath.Join(repoDir, ".git", "info", "exclude")
194→
195→	data, err := os.ReadFile(excludePath)
196→	if err != nil && !errors.Is(err, os.ErrNotExist) {
197→		return fmt.Errorf("read %s: %w", excludePath, err)
198→	}
199→
200→	normalized := strings.ReplaceAll(string(data), "\r\n", "\n")
201→	for _, line := range strings.Split(normalized, "\n") {
202→		if strings.TrimSpace(line) == entry {
203→			return nil
204→		}
205→	}
206→
207→	var b strings.Builder
208→	if len(data) > 0 {
209→		b.Write(data)
210→		if data[len(data)-1] != '\n' {
211→			b.WriteByte('\n')
212→		}
213→	}
214→	b.WriteString(entry)
215→	b.WriteByte('\n')
216→
217→	if err := os.MkdirAll(filepath.Dir(excludePath), 0o755); err != nil {
218→		return fmt.Errorf("create %s: %w", filepath.Dir(excludePath), err)
219→	}
220→	if err := os.WriteFile(excludePath, []byte(b.String()), 0o644); err != nil {
221→		return fmt.Errorf("write %s: %w", excludePath, err)
222→	}
223→	return nil
224→}
