226→// ForEachAgent runs fn as a parallel subtest for every registered agent.
227→// It handles repo setup, concurrency gating, context timeout, and cleanup.
228→// The timeout is scaled by each agent's TimeoutMultiplier.
229→//
230→// If RunPrompt detects a transient API error (e.g. rate limit, token refresh
231→// failure), it panics with errScenarioRestart. ForEachAgent recovers from the
232→// panic and restarts the entire scenario with a fresh repository, up to
233→// maxScenarioRestarts times. This avoids stale CLI session state from the
234→// failed attempt poisoning the retry.
235→func ForEachAgent(t *testing.T, timeout time.Duration, fn func(t *testing.T, s *RepoState, ctx context.Context)) {
236→	t.Helper()
237→	t.Parallel()
238→	all := agents.All()
239→	if len(all) == 0 {
240→		t.Skip("no agents registered (check E2E_AGENT filter)")
241→	}
242→	for _, agent := range all {
243→		t.Run(agent.Name(), func(t *testing.T) {
244→			// Use the global test deadline for slot wait so we don't
245→			// skip prematurely — only bail if the whole binary is dying.
246→			slotCtx := context.Background()
247→			if deadline, ok := t.Deadline(); ok {
248→				var cancel context.CancelFunc
249→				slotCtx, cancel = context.WithDeadline(slotCtx, deadline)
250→				defer cancel()
251→			}
252→			if err := agents.AcquireSlot(slotCtx, agent); err != nil {
253→				t.Fatalf("timed out waiting for agent slot: %v", err)
254→			}
255→			defer agents.ReleaseSlot(agent)
256→
257→			// Per-test timeout starts after slot is acquired, scaled
258→			// by the agent's multiplier (e.g. 2.5× for gemini).
259→			scaled := time.Duration(float64(timeout) * agent.TimeoutMultiplier())
260→
261→			var prevState *RepoState
262→			for attempt := range maxScenarioRestarts + 1 {
263→				s := SetupRepo(t, agent)
264→				ctx, cancel := context.WithTimeout(context.Background(), scaled)
265→
266→				// On restart, suppress artifact capture from the previous
267→				// failed attempt so it doesn't overwrite the final one.
268→				if prevState != nil {
269→					prevState.skipArtifacts = true
270→				}
271→
272→				restarted := runScenario(t, s, ctx, fn)
273→				cancel()
274→
275→				if !restarted {
276→					return
277→				}
278→				prevState = s
279→				if attempt >= maxScenarioRestarts {
280→					t.Fatalf("exhausted %d scenario attempts due to transient API errors", maxScenarioRestarts+1)
281→				}
282→				t.Logf("transient error, restarting scenario (attempt %d/%d)", attempt+2, maxScenarioRestarts+1)
283→			}
284→		})
285→	}
286→}
287→
288→// runScenario runs the test function and recovers from errScenarioRestart
289→// panics triggered by transient API errors in RunPrompt. Returns true if
290→// the scenario should be restarted with a fresh repository.
291→func runScenario(t *testing.T, s *RepoState, ctx context.Context, fn func(t *testing.T, s *RepoState, ctx context.Context)) (restarted bool) {
292→	t.Helper()
293→	defer func() {
294→		if r := recover(); r != nil {
295→			if _, ok := r.(errScenarioRestart); ok {
296→				restarted = true
297→				return
298→			}
299→			panic(r) // re-panic for unexpected panics
300→		}
301→	}()
302→	fn(t, s, ctx)
303→	return false
304→}
305→
306→const maxScenarioRestarts = 2 // restart up to 2 times = 3 total attempts
307→
308→// errScenarioRestart is panicked by RunPrompt when a transient API error is
309→// detected. ForEachAgent recovers from this panic and restarts the test
310→// scenario with a fresh repository, avoiding stale CLI state from the failed
311→// attempt.
312→type errScenarioRestart struct {
313→	msg string
314→}
315→
316→// RunPrompt runs an agent prompt, logs the command and output to ConsoleLog,
317→// and returns the result. If the agent reports a transient API error, it
318→// panics with errScenarioRestart to trigger a full scenario restart in
319→// ForEachAgent (see runScenario).
320→func (s *RepoState) RunPrompt(t *testing.T, ctx context.Context, prompt string, opts ...agents.Option) (agents.Output, error) {
321→	t.Helper()
322→	out, err := s.Agent.RunPrompt(ctx, s.Dir, prompt, opts...)
323→	s.logPromptResult(out)
324→
325→	if err != nil && s.Agent.IsTransientError(out, err) {
326→		errMsg := fmt.Sprintf("transient API error (stderr: %s)", strings.TrimSpace(out.Stderr))
327→		t.Logf("%s — restarting scenario", errMsg)
328→		fmt.Fprintf(s.ConsoleLog, "> [transient] %s — restarting scenario\n", errMsg)
329→		panic(errScenarioRestart{msg: errMsg})
330→	}
331→
332→	return out, err
333→}
334→
335→func (s *RepoState) logPromptResult(out agents.Output) {
336→	s.ConsoleLog.WriteString("> " + out.Command + "\n")
337→	s.ConsoleLog.WriteString("stdout:\n" + out.Stdout + "\n")
338→	s.ConsoleLog.WriteString("stderr:\n" + out.Stderr + "\n")
339→}
