341→// Git runs a git command in the repo and logs it to ConsoleLog.
342→func (s *RepoState) Git(t *testing.T, args ...string) {
343→	t.Helper()
344→	s.ConsoleLog.WriteString("> git " + strings.Join(args, " ") + "\n")
345→	Git(t, s.Dir, args...)
346→}
