364→// WaitFor waits for a pattern in the interactive session's pane and logs the
365→// pane content to ConsoleLog after the wait completes (success or failure).
366→func (s *RepoState) WaitFor(t *testing.T, session agents.Session, pattern string, timeout time.Duration) {
367→	t.Helper()
368→	content, err := session.WaitFor(pattern, timeout)
369→	fmt.Fprintf(s.ConsoleLog, "> pane after WaitFor(%q):\n%s\n", pattern, content)
370→	if err != nil {
371→		t.Fatalf("WaitFor(%q): %v", pattern, err)
372→	}
373→}
