385→// PatchSettings merges extra keys into .entire/settings.json.
386→func PatchSettings(t *testing.T, dir string, extra map[string]any) {
387→	t.Helper()
388→	path := filepath.Join(dir, ".entire", "settings.json")
389→	data, err := os.ReadFile(path)
390→	if err != nil {
391→		t.Fatalf("read settings: %v", err)
392→	}
393→	var settings map[string]any
394→	if err := json.Unmarshal(data, &settings); err != nil {
395→		t.Fatalf("parse settings: %v", err)
396→	}
397→	for k, v := range extra {
398→		settings[k] = v
399→	}
400→	out, err := json.MarshalIndent(settings, "", "  ")
401→	if err != nil {
402→		t.Fatalf("marshal settings: %v", err)
403→	}
404→	if err := os.WriteFile(path, out, 0o644); err != nil {
405→		t.Fatalf("write settings: %v", err)
406→	}
407→}
