409→// Git runs a git command in the given directory and fails the test if it
410→// returns a non-zero exit code.
411→func Git(t *testing.T, dir string, args ...string) {
412→	t.Helper()
413→
414→	cmd := exec.Command("git", args...)
415→	if dir != "" {
416→		cmd.Dir = dir
417→	}
418→	cmd.Env = append(os.Environ(), "ENTIRE_TEST_TTY=0")
419→
420→	out, err := cmd.CombinedOutput()
421→	if err != nil {
422→		t.Fatalf("git %s failed: %v\n%s", strings.Join(args, " "), err, out)
423→	}
424→}
425→
426→// GitOutput runs a git command in the given directory, returns its trimmed
427→// stdout, and fails the test on error.
428→func GitOutput(t *testing.T, dir string, args ...string) string {
429→	t.Helper()
430→
431→	cmd := exec.Command("git", args...)
432→	if dir != "" {
433→		cmd.Dir = dir
434→	}
435→
436→	out, err := cmd.Output()
437→	if err != nil {
438→		var stderr string
439→		ee := &exec.ExitError{}
440→		if errors.As(err, &ee) {
